WITH recent_departments AS (SELECT *, COALESCE(budget, 0) AS budget_filled FROM departments WHERE dept_name <> 'Finance'), location_summary AS (SELECT location, SUM(CASE WHEN dept_name = 'Marketing' THEN budget_filled ELSE 0 END) AS marketing_budget_filled FROM recent_departments GROUP BY location) SELECT location, marketing_budget_filled FROM location_summary WHERE marketing_budget_filled >= 64 ORDER BY marketing_budget_filled DESC;
